def count_cycles(m):
    """
    Counts the number of disjoint cycles for the permutation x -> 3x mod m 
    on the set {1, 2, ..., m-1}, given that m is not divisible by 3.
    """
    if m <= 1 or m % 3 == 0:
        return None  # Invalid input based on problem constraints

    elements = list(range(1, m))
    visited = [False] * m  # Index 0 is unused, indices 1 to m-1 are for elements

    cycle_count = 0

    for i in range(1, m):
        if not visited[i]:
            cycle_count += 1
            current = i
            while not visited[current]:
                visited[current] = True
                # Calculate the next element: 3 * current mod m
                next_val = (3 * current) % m
                # Since m is not divisible by 3, next_val will be in {1, ..., m-1}
                current = next_val

    return cycle_count

