def get_order(a, m):
    phi_m = m - 1 if m > 1 else 1
    factors = []
    d = 2
    temp = phi_m
    while d * d <= temp:
        if temp % d == 0:
            factors.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)

    for q in factors:
        if pow(a, phi_m // q, m) == 1:
            return None  # Not a primitive root, order is smaller than phi_m
    return phi_m

